CREATE OR REPLACE EDITIONABLE PROCEDURE "%USER_NAME%"."SP_REGISTRAR_PAGO" ( p_id_cuota IN NUMBER, p_monto IN NUMBER, p_metodo_pago IN VARCHAR2, p_referencia IN VARCHAR2, p_comprobante_url IN VARCHAR2, p_id_usuario IN NUMBER, p_ip_origen IN VARCHAR2, p_id_pago_out OUT NUMBER ) AS BEGIN INSERT INTO PAGO ( id_cuota, monto_pagado, metodo_pago, referencia, comprobante_url, estado, creado_por ) VALUES ( p_id_cuota, p_monto, p_metodo_pago, p_referencia, p_comprobante_url, 'PENDIENTE', p_id_usuario ) RETURNING id_pago INTO p_id_pago_out;
INSERT INTO BITACORA_AUDITORIA ( id_usuario, modulo, accion, tabla_afectada, id_registro_afectado, valor_nuevo, ip_origen ) VALUES ( p_id_usuario, 'PAGOS', 'REGISTRAR_COMPROBANTE', 'PAGO', p_id_pago_out, '{"id_cuota": ' || p_id_cuota || ', "monto": ' || p_monto || ', "estado": "PENDIENTE"}', p_ip_origen );
COMMIT; EXCEPTION WHEN OTHERS THEN ROLLBACK; RAISE; END SP_REGISTRAR_PAGO; /
